import { projectmanagerList } from '@/api/assets/projectManage'

export default {
  props: {
    placeholder: {
      type: String
    },
    type: {
      type: String
    },
    disabled: {
      type: Boolean
    },
    value: {
      type: [String, Number, Array],
      default: ""
    }
  },
  watch: {
    value(val) {
      this.myValue = val;
      this.$emit("input", val);
    }
  },
  data() {
    return {
      isShow: false,
      searchForm: {
        current: 1,
        size: 20
      },
      // 表格
      tableData: [
        {eprNum: 2023},
        {eprNum: 220},
      ],
      tableHeight: '550px',
      tableLoading: false,
      total: 0,
      selectList: [],
      list: [],
      myValue: this.value
    };
  },
  created() {
    this.getList()
  },
  methods: {
    select(val) {
      this.selectList = val;
    },
    handleClick(){
      if (this.disabled) {
        return
      }
      this.isShow = true
      this.getList()
    },
    getList() {
      this.tableLoading = true
      this.searchForm.projectUnitCode = this.$store.state.user.userDetail.erpUnitCode
      projectmanagerList(this.searchForm).then(res => {
        this.tableData = res.data.records
        this.total = res.data.total
        this.tableLoading = false
      }).catch(() => {
        this.tableLoading = false
      })
    },
    handleSubmit(){
      if (this.selectList.length != 1) {
        this.$message.warning("请选择一条数据!")
        return
      }
      if( this.type == 'wbsElement' ){
        this.$emit('input', this.selectList[0].wbsCode)
      }else if( this.type == 'wbsProject' ){
        this.$emit('input', this.selectList[0].wbsName)
      }
      this.$emit("change", this.selectList[0], this.type);
      this.isShow = false
    },
    handleSEmpty(){
      this.$emit('input', undefined)
      this.$emit("change", {}, this.type);
      this.isShow = false
    },
    // 查询
    handleQuery() {
      this.searchForm.current = 1
      this.getList()
    },
    // 重置
    searchReset() {
      this.searchForm = {
        current: 1,
        size: 20
      }
      this.getList()
    },
    handleSave(row){
      //保存
      if( this.type == 'wbsElement' ){
        this.$emit('input', row.wbsCode)
      }else if( this.type == 'wbsProject' ){
        this.$emit('input', row.wbsName)
      }
      this.$emit("change", row, this.type);
      this.isShow = false
    }
  }
};
